eplace function graphql_public.graphql(\n            \"operationName\" text default null,\n            query text default null,\n            variables jsonb default null,\n            extensions jsonb default null\n        )\n            returns jsonb\n            language plpgsql\n            set search_path to ''''\n        as $$\n            DECLARE\n                server_version float;\n            BEGIN\n                server_version = (SELECT (SPLIT_PART((select version()), '' '', 2))::float);\n\n                IF server_version >= 14 THEN\n                    RETURN jsonb_build_object(\n                        ''errors'', jsonb_build_array(\n                            jsonb_build_object(\n                                ''message'', ''pg_graphql extension is not enabled.''\n                            )\n                        )\n                    );\n                ELSE\n                    RETURN jsonb_build_object(\n                        ''errors'', jsonb_build_array(\n                            jsonb_build_object(\n                                ''message'', ''pg_graphql is only available on projects running Postgres 14 onwards.''\n                            )\n                        )\n                    );\n                END IF;\n            END;\n        $$;\n    END IF;\n\n    END;\n$function$\n", "security_definer": false}, "pgrst_ddl_watch": {"tags": null, "event": "ddl_command_end", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.pgrst_ddl_watch()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nDECLARE\n  cmd record;\nBEGIN\n  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    IF cmd.command_tag IN (\n      ''CREATE SCHEMA'', ''ALTER SCHEMA''\n    , ''CREATE TABLE'', ''CREATE TABLE AS'', ''SELECT INTO'', ''ALTER TABLE''\n    , ''CREATE FOREIGN TABLE'', ''ALTER FOREIGN TABLE''\n    , ''CREATE VIEW'', ''ALTER VIEW''\n    , ''CREATE MATERIALIZED VIEW'', ''ALTER MATERIALIZED VIEW''\n    , ''CREATE FUNCTION'', ''ALTER FUNCTION''\n    , ''CREATE TRIGGER''\n    , ''CREATE TYPE'', ''ALTER TYPE''\n    , ''CREATE RULE''\n    , ''COMMENT''\n    )\n    -- don''t notify in case of CREATE TEMP table or other objects created on pg_temp\n    AND cmd.schema_name is distinct from ''pg_temp''\n    THEN\n      NOTIFY pgrst, ''reload schema'';\n    END IF;\n  END LOOP;\nEND; $function$\n", "security_definer": false}, "pgrst_drop_watch": {"tags": null, "event": "sql_drop", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION extensions.pgrst_drop_watch()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\nDECLARE\n  obj record;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()\n  LOOP\n    IF obj.object_type IN (\n      ''schema''\n    , ''table''\n    , ''foreign table''\n    , ''view''\n    , ''materialized view''\n    , ''function''\n    , ''trigger''\n    , ''type''\n    , ''rule''\n    )\n    AND obj.is_temporary IS false -- no pg_temp objects\n    THEN\n      NOTIFY pgrst, ''reload schema'';\n    END IF;\n  END LOOP;\nEND; $function$\n", "security_definer": false}, "graphql_watch_ddl": {"tags": null, "event": "ddl_command_end", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION graphql.increment_schema_version()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nbegin\n    perform pg_catalog.nextval(''graphql.seq_schema_version'');\nend;\n$function$\n", "security_definer": true}, "graphql_watch_drop": {"tags": null, "event": "sql_drop", "owner": "supabase_admin", "enabled": "O", "definition": "CREATE OR REPLACE FUNCTION graphql.increment_schema_version()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nbegin\n    perform pg_catalog.nextval(''graphql.seq_schema_version'');\nend;\n$function$\n", "security_definer": true}, "issue_pg_cron